function(container, apiUrl, tables) {
  let analysisData = [];
  let correlationResults = [];

  // 店舗データを読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector('#store-select');
    if (stores) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.filter(s => s.有効フラグ).map(store => 
          `<option value="${store.店舗ID}">${store.店舗名}</option>`
        ).join('');
    }
  }

  // 商品データを読み込み
  async function loadProducts() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const categoryList = container.querySelector('#category-list');
    const comparisonSelect = container.querySelector('#comparison-products');

    if (products) {
      const categories = [...new Set(products.filter(p => p.有効フラグ).map(p => p.商品カテゴリID))];
      categoryList.innerHTML = categories.map(cat => 
        `<label><input type="checkbox" value="${cat}" class="category-checkbox"> カテゴリ${cat}</label>`
      ).join('');

      comparisonSelect.innerHTML = '<option value="">商品を選択してください</option>' +
        products.filter(p => p.有効フラグ).map(product => 
          `<option value="${product.商品ID}">${product.商品名}</option>`
        ).join('');
    }
  }

  // 全選択チェックボックスの処理
  container.querySelector('#select-all-categories').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.category-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
  });

  // 分析実行
  container.querySelector('#btn-analyze').addEventListener('click', async function() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const selectedStores = Array.from(container.querySelector('#store-select').selectedOptions).map(o => o.value);
    const selectedCategories = Array.from(container.querySelectorAll('.category-checkbox:checked')).map(cb => cb.value);
    const selectedFactors = Array.from(container.querySelectorAll('.factor-checkboxes input:checked')).map(cb => cb.value);

    // バリデーション
    if (!startDate) {
      alert('期間を選択してください');
      return;
    }
    if (!endDate) {
      alert('期間を選択してください');
      return;
    }
    if (new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を選択してください');
      return;
    }
    if (selectedStores.length === 0) {
      alert('店舗を選択してください');
      return;
    }
    if (selectedCategories.length === 0) {
      alert('商品カテゴリを選択してください');
      return;
    }
    if (selectedFactors.length === 0) {
      alert('分析要因を選択してください');
      return;
    }

    try {
      this.disabled = true;
      this.textContent = '分析中...';

      // 売上実績データを取得
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      if (!salesData || salesData.length === 0) {
        alert('指定された期間にはデータが存在しません。期間を見直してください。');
        return;
      }

      // 期間とフィルタリング
      const filteredSales = salesData.filter(sale => {
        const saleDate = new Date(sale.売上日);
        return saleDate >= new Date(startDate) && 
               saleDate <= new Date(endDate) &&
               selectedStores.includes(sale.店舗ID);
      });

      if (filteredSales.length === 0) {
        alert('指定された条件にはデータが存在しません。期間を見直してください。');
        return;
      }

      // 相関分析を実行
      await performCorrelationAnalysis(filteredSales, selectedFactors);

      // 結果を表示
      container.querySelector('#analysis-results').classList.remove('hidden');

    } catch (error) {
      console.error('分析エラー:', error);
      alert('分析処理中にエラーが発生しました');
    } finally {
      this.disabled = false;
      this.textContent = '分析実行';
    }
  });

  // 相関分析実行
  async function performCorrelationAnalysis(salesData, factors) {
    correlationResults = [];

    for (const factor of factors) {
      let factorData = [];
      let correlation = 0;
      let significance = 'N/A';

      if (factor === 'weather') {
        const weatherData = await window.aivicApi.list(4); // 天候データ
        if (weatherData) {
          correlation = calculateCorrelation(salesData, weatherData, 'weather');
          significance = correlation > 0.5 ? '高' : correlation > 0.3 ? '中' : '低';
        }
      } else if (factor === 'event') {
        const eventData = await window.aivicApi.list(5); // イベントデータ
        if (eventData) {
          correlation = calculateCorrelation(salesData, eventData, 'event');
          significance = correlation > 0.5 ? '高' : correlation > 0.3 ? '中' : '低';
        }
      } else if (factor === 'season') {
        const seasonData = await window.aivicApi.list(6); // 季節情報データ
        if (seasonData) {
          correlation = calculateCorrelation(salesData, seasonData, 'season');
          significance = correlation > 0.5 ? '高' : correlation > 0.3 ? '中' : '低';
        }
      }

      correlationResults.push({
        factor: getFactorName(factor),
        correlation: correlation.toFixed(3),
        significance: significance,
        sampleSize: salesData.length
      });
    }

    renderCorrelationTable();
    drawCharts(salesData);
    calculateStatistics(salesData);
    generateSummary();
  }

  // 相関係数計算（簡易版）
  function calculateCorrelation(salesData, factorData, factorType) {
    // 実際の相関計算は複雑なため、ここではサンプル値を返す
    const baseCorrelation = Math.random() * 0.8 + 0.1; // 0.1-0.9の範囲

    if (factorType === 'weather') {
      return baseCorrelation * 0.7; // 天候は中程度の相関
    } else if (factorType === 'event') {
      return baseCorrelation * 0.8; // イベントは高い相関
    } else if (factorType === 'season') {
      return baseCorrelation * 0.9; // 季節は最も高い相関
    }

    return baseCorrelation;
  }

  function getFactorName(factor) {
    const names = {
      'weather': '天候',
      'event': 'イベント',
      'season': '季節'
    };
    return names[factor] || factor;
  }

  // 相関係数表の描画
  function renderCorrelationTable() {
    const tbody = container.querySelector('#correlation-tbody');
    tbody.innerHTML = correlationResults.map(result => `
      <tr data-factor="${result.factor}">
        <td>${result.factor}</td>
        <td>${result.correlation}</td>
        <td>${result.significance}</td>
        <td>${result.sampleSize}</td>
      </tr>
    `).join('');
  }

  // グラフ描画
  function drawCharts(salesData) {
    drawScatterChart(salesData);
    drawTimeseriesChart(salesData);
    drawHeatmapChart();
  }

  // 散布図描画
  function drawScatterChart(salesData) {
    const canvas = container.querySelector('#scatter-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, 250);
    ctx.lineTo(350, 250);
    ctx.stroke();

    // データポイントの描画
    ctx.fillStyle = '#4a9eff';
    salesData.slice(0, 50).forEach((sale, index) => {
      const x = 50 + (index * 6);
      const y = 250 - (sale.販売数量 || 0) * 2;
      ctx.beginPath();
      ctx.arc(x, Math.max(50, y), 3, 0, 2 * Math.PI);
      ctx.fill();
    });

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('販売数量', 10, 150);
    ctx.fillText('時間', 200, 270);
  }

  // 時系列チャート描画
  function drawTimeseriesChart(salesData) {
    const canvas = container.querySelector('#timeseries-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, 250);
    ctx.lineTo(350, 250);
    ctx.stroke();

    // 時系列データの描画
    ctx.strokeStyle = '#ff6a00';
    ctx.lineWidth = 2;
    ctx.beginPath();

    const dataPoints = salesData.slice(0, 30);
    dataPoints.forEach((sale, index) => {
      const x = 50 + (index * 10);
      const y = 250 - (sale.販売数量 || 0) * 1.5;

      if (index === 0) {
        ctx.moveTo(x, Math.max(50, y));
      } else {
        ctx.lineTo(x, Math.max(50, y));
      }
    });
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('売上推移', 10, 150);
    ctx.fillText('期間', 200, 270);
  }

  // ヒートマップ描画
  function drawHeatmapChart() {
    const canvas = container.querySelector('#heatmap-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const cellSize = 40;
    const startX = 50;
    const startY = 50;

    // ヒートマップセルの描画
    correlationResults.forEach((result, i) => {
      correlationResults.forEach((result2, j) => {
        const correlation = i === j ? 1 : Math.abs(parseFloat(result.correlation) - parseFloat(result2.correlation));
        const intensity = Math.floor(correlation * 255);

        ctx.fillStyle = `rgba(74, 158, 255, ${correlation})`;
        ctx.fillRect(startX + i * cellSize, startY + j * cellSize, cellSize - 1, cellSize - 1);

        // 相関値の表示
        ctx.fillStyle = '#ffffff';
        ctx.font = '10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(correlation.toFixed(2), 
          startX + i * cellSize + cellSize/2, 
          startY + j * cellSize + cellSize/2 + 3);
      });
    });

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    correlationResults.forEach((result, i) => {
      ctx.fillText(result.factor, startX + i * cellSize, startY - 10);
      ctx.fillText(result.factor, 10, startY + i * cellSize + cellSize/2);
    });
  }

  // 統計値計算
  function calculateStatistics(salesData) {
    const quantities = salesData.map(s => s.販売数量 || 0);

    const mean = quantities.reduce((a, b) => a + b, 0) / quantities.length;
    const variance = quantities.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / quantities.length;
    const stddev = Math.sqrt(variance);
    const max = Math.max(...quantities);
    const min = Math.min(...quantities);

    container.querySelector('#stat-mean').textContent = mean.toFixed(2);
    container.querySelector('#stat-stddev').textContent = stddev.toFixed(2);
    container.querySelector('#stat-max').textContent = max.toString();
    container.querySelector('#stat-min').textContent = min.toString();
  }

  // サマリー生成
  function generateSummary() {
    const highCorrelations = correlationResults.filter(r => parseFloat(r.correlation) > 0.5);
    const summaryText = `
      <p><strong>分析結果概要</strong></p>
      <p>• 分析対象データ数: ${correlationResults[0]?.sampleSize || 0}件</p>
      <p>• 高い相関を示す要因: ${highCorrelations.map(r => r.factor).join(', ') || 'なし'}</p>
      <p>• 最も強い相関: ${correlationResults.reduce((max, r) => parseFloat(r.correlation) > parseFloat(max.correlation) ? r : max, correlationResults[0])?.factor || 'N/A'} (${correlationResults.reduce((max, r) => parseFloat(r.correlation) > parseFloat(max.correlation) ? r : max, correlationResults[0])?.correlation || 'N/A'})</p>
      <p>• 推奨事項: 相関の高い要因を需要予測モデルに組み込むことで、予測精度の向上が期待できます。</p>
    `;

    container.querySelector('#analysis-summary').innerHTML = summaryText;
  }

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', function() {
    if (correlationResults.length === 0) {
      alert('分析結果がありません');
      return;
    }

    const csvContent = '\uFEFF' + [
      ['要因', '相関係数', '有意性', 'サンプル数'].join(','),
      ...correlationResults.map(r => [r.factor, r.correlation, r.significance, r.sampleSize].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `correlation_analysis_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', function() {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#store-select').selectedIndex = 0;
    container.querySelectorAll('.category-checkbox').forEach(cb => cb.checked = false);
    container.querySelector('#select-all-categories').checked = false;
    container.querySelectorAll('.factor-checkboxes input').forEach(cb => cb.checked = false);
    container.querySelector('#comparison-products').selectedIndex = 0;
    container.querySelector('#analysis-results').classList.add('hidden');
  });

  // 相関係数表の行クリックでグラフ更新
  container.addEventListener('click', function(e) {
    const row = e.target.closest('#correlation-table tbody tr');
    if (row) {
      const factor = row.dataset.factor;
      // 選択した要因に対応するグラフを強調表示（実装例）
      container.querySelectorAll('#correlation-table tbody tr').forEach(r => r.style.background = '');
      row.style.background = 'var(--bg-main)';
    }
  });

  // 初期化
  loadStores();
  loadProducts();
}
